import sys

s = sys.stdin.read().split()[0]
V = set('aeiou')
n = len(s)
best = ''
for i in range(n):
    for j in range(i + 2, n):
        if s[i] in V and s[j] in V and all(ch not in V for ch in s[i + 1:j]):
            cand = s[i + 1:j]
            if len(cand) > len(best):
                best = cand
print(best if best else -1)

